export const nlpLessons:NLesson[]=[
{id:'sentiment',course:0,title:"Sentiment classification",en:'Logistic regression',intro:"Convert text signals into a score, then into a positive-sentiment probability.",example:"A message with positive and negative signals. Weights are fixed educational values, not a trained language model.",symbols:"x₊ and x₋: signal counts · b: bias · z: score · p: positive-class probability.",formula:String.raw`z=b+w_+x_++w_-x_-,\qquad p=\sigma(z)=\frac{1}{1+e^{-z}}`,controls:[c('pos',"Positive signals x₊",2,0,6,1),c('neg',"Negative signals x₋",1,0,6,1),c('b',"Bias b",0,-3,3)],calculate:({pos,neg,b})=>{const z=b+1.2*pos-neg,p=sig(z);return{tex:String.raw`p=${f(p)}`,meaning:String.raw`Educational positive probability: ${(100*p).toFixed(1)}%; at threshold 0.5 the class is ${p>=.5?"positive":"negative"}.`,steps:[s("Convert text to features","Count signals in this example. Real classification requires text processing and training data.",String.raw`x=(1,${pos},${neg}),\quad w=(${f(b)},1.2,-1)`),s("Combine weighted signals","Positive signals increase the score; negative signals decrease it.",String.raw`z=${f(b)}+1.2(${pos})-(${neg})=${f(z)}`),s("Calculate probability","Sigmoid maps the score between zero and one.",String.raw`p=\frac{1}{1+e^{-(${f(z)})}}=${f(p)}`)],bars:[{label:"Positive",value:p},{label:"Negative",value:1-p}],quiz:{question:"What is z before Sigmoid?",answer:z,why:"Add bias and 1.2 times positive signals, then subtract negative signals."}}}},
{id:'bayes',course:0,title:"Naive Bayes and log odds",en:'Naïve Bayes',intro:"Combine word evidence with prior class knowledge. Logarithms turn multiplication into addition.",example:"For one word, change its probability in positive and negative messages and calculate the class probability after observing it.",symbols:"π: positive prior · a=P(w|+) · b=P(w|−). These are conditional probabilities, not raw counts.",formula:String.raw`\ell=\log\frac{P(+)}{P(-)}+\sum_w\log\frac{P(w\mid +)}{P(w\mid -)}`,controls:[c('prior',"Positive probability before the word",.5,.05,.95,.05),c('positive',"Word probability in positive text",.7,.05,.95,.05),c('negative',"Word probability in negative text",.2,.05,.95,.05)],calculate:({prior,positive,negative})=>{const priorLog=Math.log(prior/(1-prior)),wordLog=Math.log(positive/negative),l=priorLog+wordLog,p=sig(l);return{tex:String.raw`P(+\mid w)=${f(p)}`,meaning:"This is Bayes’ rule for one word. With multiple words, naive Bayes assumes conditional independence within each class.",steps:[s("Start with prior knowledge","Calculate positive log odds before reading the word.",String.raw`\log\frac{${f(prior)}}{${f(1-prior)}}=${f(priorLog)}`),s("Add word evidence","A word more likely in positive text contributes more positively.",String.raw`\log\frac{${f(positive)}}{${f(negative)}}=${f(wordLog)}`),s("Convert odds to probability","Add the terms and apply the logistic transform.",String.raw`\ell=${f(l)},\quad P(+\mid w)=\sigma(\ell)=${f(p)}`)],bars:[{label:"Before the word",value:prior},{label:"After the word",value:p}],quiz:{question:"What is the log ratio of the two word probabilities alone?",answer:wordLog,why:"Calculate ln(a/b) using the natural logarithm."}}}},
{id:'cosine',course:0,title:"Word similarity through direction",en:'Cosine similarity',intro:"Compare the directions of word vectors rather than just their lengths.",example:"Query u=(1,1) and an adjustable document vector v. These are synthetic numbers; similarity is geometric.",symbols:"u and v: vectors · dot: dot product · ‖u‖: vector length.",formula:String.raw`\operatorname{cos}(u,v)=\frac{u\cdot v}{\lVert u\rVert\lVert v\rVert}`,controls:[c('x',"First component of v",1,-3,3),c('y',"Second component of v",2,-3,3)],calculate:({x,y})=>{const norm=Math.hypot(x,y),dot=x+y,cos=norm?dot/(Math.sqrt(2)*norm):null;return{tex:cos===null?String.raw`v=0\quad\Rightarrow\quad\text{undefined}`:String.raw`\operatorname{cos}(u,v)=${f(cos)}`,meaning:cos===null?"Similarity is undefined for a zero vector; change a component.":"Values range from −1 to 1: same direction near 1, perpendicular near 0, opposite near −1.",steps:[s("Multiply components and add","The dot product captures component alignment.",String.raw`u\cdot v=1(${f(x)})+1(${f(y)})=${f(dot)}`),s("Calculate each vector length","Take the square root of the sum of squared components.",String.raw`\lVert u\rVert=\sqrt2,\quad\lVert v\rVert=${f(norm)}`),s("Divide by both lengths","This removes the effect of positive scaling.",cos===null?String.raw`\frac{0}{0}\quad\text{undefined}`:String.raw`\frac{${f(dot)}}{\sqrt2\cdot ${f(norm)}}=${f(cos)}`)],bars:[{label:"Dot product",value:dot},{label:"Length of v",value:norm}],quiz:{question:"What is u·v?",answer:dot,why:"Add v’s components because both components of u are 1."}}}},
{id:'alignment',course:0,title:"Align two word spaces",en:'Linear word-vector alignment',intro:"Learn a linear transformation that brings vectors in one language close to their counterparts in another.",example:"Use row vector x=(1,2) and target y=(2,1). Adjust a diagonal matrix only to illustrate multiplication.",symbols:"X: source vectors · R: transformation · Y: targets · ‖·‖F: Frobenius norm.",formula:String.raw`\widehat Y=XR,\qquad L=\frac{1}{m}\lVert XR-Y\rVert_F^2`,controls:[c('a',"First diagonal entry",1,-2,3),c('d',"Second diagonal entry",1,-2,3)],calculate:({a,d})=>{const error=(a-2)**2+(2*d-1)**2;return{tex:String.raw`\widehat y=(${f(a)},${f(2*d)}),\quad L=${f(error)}`,meaning:"For this sample alone, loss is zero at a=2 and d=0.5. Real alignment learns a full matrix from many word pairs.",steps:[s("Multiply vector and matrix","This is a row vector: use xR, not Rx.",String.raw`(1,2)\begin{bmatrix}${f(a)}&0\\0&${f(d)}\end{bmatrix}=(${f(a)},${f(2*d)})`),s("Compare with the target","Subtract corresponding target components.",String.raw`\widehat y-y=(${f(a-2)},${f(2*d-1)})`),s("Measure error","With one sample, sum the two squared differences.",String.raw`L=(${f(a-2)})^2+(${f(2*d-1)})^2=${f(error)}`)],bars:[{label:"First predicted component",value:a},{label:"Second predicted component",value:2*d},{label:"Loss",value:error}],quiz:{question:"With a=2, which d makes the loss zero?",answer:.5,why:"We need 2d=1, so d=0.5."}}}},
{id:'edit',course:1,title:"Edit distance and correction",en:'Minimum edit distance',intro:"Find the minimum insertions, deletions, and substitutions needed to transform one word into another.",example:"Change both words and follow the dynamic programming table. Each edit costs 1; a match costs 0. Applications may use other weights.",symbols:"D(i,j): cost to transform the first i source characters into the first j target characters.",formula:String.raw`D_{i,j}=\min\!\left(D_{i-1,j}+1,\ D_{i,j-1}+1,\ D_{i-1,j-1}+\mathbf1[x_i\ne y_j]\right)`,controls:[],texts:[{key:'source',label:"Source word",value:"book",max:12},{key:'target',label:"Target word",value:"books",max:12}],calculate:(_,t)=>{const r=editDistance(t.source,t.target);return{tex:String.raw`D(${r.x.length},${r.y.length})=${r.distance}`,meaning:"The final cell is the minimum cost. Matching is literal after Unicode normalization; Arabic diacritics and hamza variants are not ignored.",steps:[s("Initialize the first row and column","Turning a word into an empty string deletes all characters; the reverse inserts them.",String.raw`D(i,0)=i,\quad D(0,j)=j`),s("Choose the cheapest path to each cell","Compare deletion, insertion, and substitution or matching, retaining the minimum.",String.raw`D_{i,j}=\min(\text{delete},\text{insert},\text{replace})`),s("Read the final cell","This is a distance, not a word-correctness probability.",String.raw`D(${r.x.length},${r.y.length})=${r.distance}`)],bars:[{label:"Source length",value:r.x.length},{label:"Target length",value:r.y.length},{label:"Minimum cost",value:r.distance}],table:{headers:["Source / target",'∅',...r.y],rows:r.matrix.map((row,i)=>[i?r.x[i-1]:'∅',...row])},quiz:{question:"What does deleting the entire source word cost?",answer:r.x.length,why:"Each deletion costs 1, so the cost equals source length."}}}},
{id:'viterbi',course:1,title:"Most likely tag sequence",en:'HMM & Viterbi',intro:"Select the best hidden-state sequence using transition and observation probabilities.",example:"Two educational states A and B, with observations x then y. Emissions: A:(0.8,0.2), B:(0.3,0.7).",symbols:"π: starting probability · aᵢⱼ: transition · bⱼ(o): emission probability · δ: best partial-path probability.",formula:String.raw`\delta_t(j)=b_j(o_t)\max_i\left[\delta_{t-1}(i)a_{ij}\right]`,controls:[c('prior',"Probability of starting in A",.6,.05,.95,.05),c('stay',"Probability of staying in the same state",.7,.05,.95,.05)],calculate:({prior,stay})=>{const r=viterbi2(prior,stay);return{tex:String.raw`\text{path}=${r.path.map(i=>i?'B':'A').join(String.raw`\to `)},\quad P=${f(r.score)}`,meaning:"This is the joint probability of path and observations, not a normalized conditional path probability. Ties choose A first.",steps:[s("Start with the first observation","Multiply starting probability by the probability of emitting x.",String.raw`\delta_1=(${f(r.first[0])},${f(r.first[1])})`),s("Extend to the second observation","For each ending state, select the best previous state and multiply by the probability of emitting y.",String.raw`\delta_2=(${f(r.last[0])},${f(r.last[1])})`),s("Trace previous decisions","Choose the largest final value and recover its origin.",String.raw`\operatorname{argmax}P=${r.path.map(i=>i?'B':'A').join(String.raw`\to `)}`)],bars:r.paths.map(p=>({label:p.path.map(i=>i?'B':'A').join(' → '),value:p.score})),quiz:{question:"What is the probability of starting in B?",answer:1-prior,why:"There are two states and the starting probabilities sum to one."}}}},
{id:'ngram',course:1,title:"Predict the next word",en:'N-grams & smoothing',intro:"Estimate next-word probability from counts after a context, then smooth so unseen words are not impossible.",example:"For one fixed context, adjust counts of three candidate words. The vocabulary is limited to these three.",symbols:"c(h,w): context-word count · c(h): total count · α: additive smoothing · V=3.",formula:String.raw`P(w\mid h)=\frac{c(h,w)+\alpha}{c(h)+\alpha V}`,controls:[c('a',"Count of “mathematics”",4,0,10,1),c('b',"Count of “language”",2,0,10,1),c('c',"Count of “programming”",0,0,10,1),c('alpha',"Smoothing α",1,.1,2,.1)],calculate:({a,b,c,alpha})=>{const total=a+b+c,den=total+3*alpha,p=[a,b,c].map(n=>(n+alpha)/den);return{tex:String.raw`P=(${p.map(f).join(',')})`,meaning:"Smoothing assigns probability to every vocabulary item. All-zero counts produce a uniform distribution.",steps:[s("Sum observations","Count all occurrences of the context with these three words.",String.raw`c(h)=${a}+${b}+${c}=${total}`),s("Add smoothing","Add α to each count and 3α to the denominator.",String.raw`c(h)+\alpha V=${total}+3(${f(alpha)})=${f(den)}`),s("Calculate and normalize probabilities","The resulting probabilities sum to one.",String.raw`\sum_wP(w\mid h)=1`)],bars:p.map((v,i)=>({label:["Mathematics","Language","Programming"][i],value:v})),quiz:{question:"What is the denominator after smoothing?",answer:den,why:"Add the three counts and 3α."}}}},
{id:'cbow',course:1,title:"Learn a word from its context",en:'CBOW & cross-entropy',intro:"Combine context-word representations to predict the middle word. Training adjusts representations to reduce prediction error.",example:"A tiny model with one scalar per context word and two possible outputs. Mean context enters ReLU, then fixed output weights (1,−1).",symbols:"e₁,e₂: context embeddings · h: post-ReLU state · p: distribution · L: loss for the first target word.",formula:String.raw`h=\operatorname{ReLU}\!\left(\frac{e_1+e_2}{2}\right),\quad p=\operatorname{softmax}(h,-h),\quad L=-\log p_1`,controls:[c('a',"First context embedding",1,-3,3),c('b',"Second context embedding",2,-3,3)],calculate:({a,b})=>{const avg=(a+b)/2,h=Math.max(0,avg),p=softmaxN([h,-h]),loss=-Math.log(p[0]);return{tex:String.raw`p_1=${f(p[0])},\quad L=${f(loss)}`,meaning:"This illustrates only the forward pass and learns no real word vectors. Full CBOW has many trainable matrices and embeddings.",steps:[s("Summarize context","Average the two representations; this example discards their order.",String.raw`\bar e=(${f(a)}+${f(b)})/2=${f(avg)}`),s("Apply activation and calculate scores","ReLU retains positive values and zeros negatives, then compute both word scores.",String.raw`h=\max(0,${f(avg)})=${f(h)},\quad z=(${f(h)},${f(-h)})`),s("Measure target-word loss","Higher probability for the correct word means lower negative log probability.",String.raw`L=-\ln(${f(p[0])})=${f(loss)}`)],bars:[{label:"Correct word",value:p[0]},{label:"Alternative word",value:p[1]}],quiz:{question:"What is the context mean before ReLU?",answer:avg,why:"Add the representations and divide by 2."}}}},
{id:'rnn',course:2,title:"Memory that moves through words",en:'Recurrent neural network',intro:"Read words sequentially and blend new input with the previous state to retain context.",example:"A numerical sequence representing three words: (1,−0.5,0.8). One hidden state, h₀=0, and input weight fixed at 1.",symbols:"xₜ: current input · hₜ₋₁: previous memory · U: recurrent weight · b: bias.",formula:String.raw`h_t=\tanh(Wx_t+Uh_{t-1}+b)`,controls:[c('u',"Memory weight U",.7,-1.5,1.5),c('b',"Bias b",0,-1,1)],calculate:({u,b})=>{const xs=[1,-.5,.8];let old=0;const hs=xs.map(x=>{old=Math.tanh(x+u*old+b);return old});return{tex:String.raw`h_3=${f(hs[2])}`,meaning:"Changing recurrent weight changes the influence of earlier words. This scalar example is not a trained text generator.",steps:xs.map((x,i)=>s(String.raw`Read word ${i+1}`,"Calculate the weighted sum and apply tanh to bound the state between −1 and 1.",String.raw`h_${i+1}=\tanh(${f(x)}+${f(u)}(${f(i?hs[i-1]:0)})+${f(b)})=${f(hs[i])}`)),bars:hs.map((v,i)=>({label:String.raw`Memory after word ${i+1}`,value:v})),quiz:{question:"What is initial state h₀ in this experiment?",answer:0,why:"We start with zero memory."}}}},
{id:'lstm',course:2,title:"Remembering and forgetting in LSTM",en:'LSTM cell',intro:"Gates control retained old memory, newly written information, and visible output.",example:"One LSTM component with previous memory 0.8 and candidate −0.4. Adjust gate values after Sigmoid.",symbols:"f: forget gate · i: input gate · o: output gate · c: cell memory · h: visible state.",formula:String.raw`c_t=f_t c_{t-1}+i_t\widetilde c_t,\qquad h_t=o_t\tanh(c_t)`,controls:[c('forget',"Retention gate f",.8,0,1,.05),c('input',"Write gate i",.3,0,1,.05),c('output',"Output gate o",.7,0,1,.05)],calculate:({forget,input,output})=>{const retained=forget*.8,written=input*-.4,cell=retained+written,h=output*Math.tanh(cell);return{tex:String.raw`c_t=${f(cell)},\quad h_t=${f(h)}`,meaning:"Gates range from 0 to 1. We control outputs directly; in a network they are computed from input and previous state using learned weights.",steps:[s("Choose what to retain","f near 1 retains old memory; near 0 forgets it.",String.raw`f_tc_{t-1}=${f(forget)}(0.8)=${f(retained)}`),s("Write new information","Add the written information to retained memory.",String.raw`c_t=${f(retained)}+${f(input)}(-0.4)=${f(cell)}`),s("Determine output","Pass memory through tanh and control visibility with the output gate.",String.raw`h_t=${f(output)}\tanh(${f(cell)})=${f(h)}`)],bars:[{label:"Retained memory",value:retained},{label:"Written information",value:written},{label:"New memory",value:cell},{label:"Output",value:h}],quiz:{question:"If output gate o=0, what is hₜ?",answer:0,why:"The output gate multiplies tanh(cₜ); multiplying by zero gives zero."}}}},
{id:'gru',course:2,title:"Update memory with GRU",en:'Gated recurrent unit',intro:"Blend old memory with a new candidate; another gate controls how much old memory contributes to that candidate.",example:"One scalar cell: x=0.5, previous h=0.8, candidate weights 1 and bias 0. Here z weights retention of the old state.",symbols:"r: reset gate · z: update gate (old-state weight here) · h̃: candidate.",formula:String.raw`\widetilde h_t=\tanh(x_t+r_t h_{t-1}),\quad h_t=z_t h_{t-1}+(1-z_t)\widetilde h_t`,controls:[c('r',"Reset gate r",.5,0,1,.05),c('z',"Old-state retention weight z",.7,0,1,.05)],calculate:({r,z})=>{const candidate=Math.tanh(.5+r*.8),h=z*.8+(1-z)*candidate;return{tex:String.raw`\widetilde h_t=${f(candidate)},\quad h_t=${f(h)}`,meaning:"z=1 retains all old state; z=0 takes the candidate. Some references reverse the update-gate convention, swapping z and 1−z.",steps:[s("Reset memory used for the candidate","r controls how the past enters the candidate calculation.",String.raw`r_th_{t-1}=${f(r)}(0.8)=${f(r*.8)}`),s("Calculate the candidate","Combine new input and gated memory, then apply tanh.",String.raw`\widetilde h_t=\tanh(0.5+${f(r*.8)})=${f(candidate)}`),s("Blend old and new","Weights z and 1−z sum to one.",String.raw`h_t=${f(z)}(0.8)+${f(1-z)}(${f(candidate)})=${f(h)}`)],bars:[{label:"Old",value:.8},{label:"Candidate",value:candidate},{label:"New",value:h}],quiz:{question:"What is hₜ when z=1 under this convention?",answer:.8,why:"z=1 retains the full previous state and zeros the candidate weight."}}}},
{id:'triplet',course:2,title:"Distinguish similar questions",en:'Triplet loss',intro:"Make a matching question closer to the reference than a different question by at least a chosen margin.",example:"Directly adjust two cosine similarities. This is a single-triplet formula; Siamese training may combine multiple losses and negative examples.",symbols:"s₊: matching similarity · s₋: nonmatching similarity · α: margin.",formula:String.raw`L=\max(0,\alpha-s_++s_-)`,controls:[c('positive',"Matching question similarity s₊",.8,-1,1,.05),c('negative',"Different question similarity s₋",.6,-1,1,.05),c('margin',"Margin α",.3,0,1,.05)],calculate:({positive,negative,margin})=>{const gap=positive-negative,loss=Math.max(0,margin-gap);return{tex:String.raw`L=${f(loss)}`,meaning:loss===0?"The gap satisfies the margin for this triplet, so there is no penalty.":"Similarities are too close; increase matching similarity or reduce nonmatching similarity.",steps:[s("Measure the gap","Subtract nonmatching similarity from matching similarity.",String.raw`s_+-s_-=${f(gap)}`),s("Compare with the margin","Calculate the shortfall from the required gap.",String.raw`\alpha-(s_+-s_-)=${f(margin-gap)}`),s("Prevent negative loss","If the margin is met, loss is zero.",String.raw`L=\max(0,${f(margin-gap)})=${f(loss)}`)],bars:[{label:"Matching similarity",value:positive},{label:"Nonmatching similarity",value:negative},{label:"Loss",value:loss}],quiz:{question:"What is s₊−s₋?",answer:gap,why:"Subtract negative-pair similarity from positive-pair similarity."}}}},
{id:'attention',course:3,title:"Attention step by step",en:'Scaled dot-product attention',intro:"Score query-key alignment, then convert scores into weights for combining values.",example:"Query q=(q₁,q₂), keys (1,0), (0,1), (1,1), and scalar values 1,2,4. Key dimension dₖ=2.",symbols:"Q: queries · K: keys · V: values · dₖ: key dimension. One query and a scalar output here.",formula:String.raw`\operatorname{Attention}(Q,K,V)=\operatorname{softmax}\left(\frac{QK^\top}{\sqrt{d_k}}\right)V`,controls:[c('x',"Component q₁",1,-3,3),c('y',"Component q₂",.5,-3,3)],reference:'https://arxiv.org/abs/1706.03762',calculate:({x,y})=>{const scores=[x,y,x+y].map(v=>v/Math.sqrt(2)),weights=softmaxN(scores),out=weights[0]+2*weights[1]+4*weights[2];return{tex:String.raw`\operatorname{output}=${f(out)}`,meaning:"The output is a weighted average between 1 and 4 here. Attention weights alone are not a causal explanation of a model decision.",steps:[s("Calculate alignment and scale","Dot the query with each key and divide by the square root of dimension.",String.raw`s=\frac{(${f(x)},${f(y)},${f(x+y)})}{\sqrt2}=(${scores.map(f).join(',')})`),s("Normalize the weights","Use Softmax; weights are positive and sum to one.",String.raw`a=\operatorname{softmax}(s)=(${weights.map(f).join(',')})`),s("Mix the values","Multiply each value by its weight and add.",String.raw`o=${f(weights[0])}(1)+${f(weights[1])}(2)+${f(weights[2])}(4)=${f(out)}`)],bars:weights.map((v,i)=>({label:String.raw`Key weight ${i+1}`,value:v})),quiz:{question:"What is the sum of attention weights?",answer:1,why:"Softmax normalizes weights to sum to one."}}}},
{id:'mask',course:3,title:"Mask future words",en:'Causal attention mask',intro:"During generation, the current token must not see later tokens. Prevent this before normalizing attention scores.",example:"Three fixed scores (1,2,3). Move the current position from 1 to 3 to see which words it may attend to.",symbols:"Mᵢⱼ: zero for past/present and −∞ for future · a: masked weights.",formula:String.raw`a_i=\operatorname{softmax}(s_i+M_i),\quad M_{ij}=\begin{cases}0&j\le i\\-\infty&j>i\end{cases}`,controls:[c('position',"Current word position",2,1,3,1)],calculate:({position})=>{const w=softmaxN([1,2,3].slice(0,position)),all=[...w,...Array(3-position).fill(0)];return{tex:String.raw`a=(${all.map(f).join(',')})`,meaning:"Future words receive zero weight. Allowed weights still sum to one; we do not apply Softmax to a fully masked row.",steps:[s("Identify allowed positions","Position i may attend to positions 1 through i.",String.raw`j\le ${position}`),s("Mask the future before Softmax","Adding −∞ makes future exponentials zero.",String.raw`e^{-\infty}=0`),s("Renormalize over allowed positions","Weights are shared only among allowed words.",String.raw`a=(${all.map(f).join(',')})`)],bars:all.map((v,i)=>({label:String.raw`Word ${i+1}${i>=position?" — masked":''}`,value:v})),quiz:{question:"How many future words are masked?",answer:3-position,why:"There are 3 total positions, and positions through the current word are allowed."}}}},
{id:'position',course:3,title:"Give words a sense of order",en:'Sinusoidal positional encoding',intro:"Add positional representations to distinguish word order using waves at different frequencies.",example:"Compute four dimensions of the original Transformer sinusoidal encoding. Other systems use different positional encodings.",symbols:"pos: position · i: dimension-pair index · d=4: embedding size. Angles are in radians.",formula:String.raw`PE_{pos,2i}=\sin\left(\frac{pos}{10000^{2i/d}}\right),\quad PE_{pos,2i+1}=\cos\left(\frac{pos}{10000^{2i/d}}\right)`,controls:[c('position',"Word position pos",3,0,30,1)],reference:'https://arxiv.org/abs/1706.03762',calculate:({position})=>{const p=[Math.sin(position),Math.cos(position),Math.sin(position/100),Math.cos(position/100)];return{tex:String.raw`PE=(${p.map(f).join(',')})`,meaning:"Each pair has a sine and cosine. The second changes more slowly because its position is divided by 100.",steps:[s("Calculate the denominators","For four dimensions, use i=0 and i=1.",String.raw`10000^0=1,\quad 10000^{2/4}=100`),s("Calculate the first pair","Take sine and cosine of the position itself.",String.raw`(\sin(${position}),\cos(${position}))=(${f(p[0])},${f(p[1])})`),s("Calculate the second pair","Use the slower angle and combine the pairs into one vector.",String.raw`(\sin(${f(position/100)}),\cos(${f(position/100)}))=(${f(p[2])},${f(p[3])})`)],bars:p.map((v,i)=>({label:String.raw`Dimension ${i}`,value:v})),quiz:{question:"What is the second pair’s denominator when d=4?",answer:100,why:"10000^(2/4) is the square root of 10000, equal to 100."}}}},
{id:'bleu',course:3,title:"Evaluate translation with BLEU",en:'BLEU-2 teaching example',intro:"Compare matching words and n-grams against a reference, penalizing overly short translations.",example:"Educational sentence-level BLEU-2 with one reference and no smoothing. Split words on whitespace and preserve punctuation as entered.",symbols:"p₁,p₂: clipped unigram/bigram precision · c,r: candidate/reference lengths · BP: brevity penalty.",formula:String.raw`BLEU_2=BP\sqrt{p_1p_2},\qquad BP=\exp\!\left(\min\left(0,1-\frac{r}{c}\right)\right)`,controls:[],texts:[{key:'candidate',label:"Model translation",value:"I enjoy learning language",max:100},{key:'reference',label:"Reference translation",value:"I enjoy learning the language",max:100}],reference:'https://aclanthology.org/P02-1040/',calculate:(_,t)=>{const r=bleu2(t.candidate,t.reference);return{tex:String.raw`BLEU_2=${f(r.score)}`,meaning:"This is not standard corpus BLEU. A valid paraphrase may not match the reference wording; the metric alone cannot establish quality.",steps:[s("Count matches without inflated repetition","A repeated word cannot earn more matches than its reference count.",String.raw`p_1=\frac{${r.one.matched}}{${r.one.total||1}}=${f(r.one.p)}`),s("Check adjacent word pairs","Without matching bigrams, the unsmoothed score is zero.",String.raw`p_2=\frac{${r.two.matched}}{${r.two.total||1}}=${f(r.two.p)}`),s("Apply brevity penalty and calculate score","An empty candidate scores zero. Combine both precisions with a geometric mean.",String.raw`BP=${f(r.bp)},\quad BLEU_2=${f(r.bp)}\sqrt{${f(r.one.p)}\cdot${f(r.two.p)}}=${f(r.score)}`)],bars:[{label:"Unigram precision p₁",value:r.one.p},{label:"Bigram precision p₂",value:r.two.p},{label:"Brevity penalty BP",value:r.bp},{label:'BLEU-2',value:r.score}],quiz:{question:"How many whitespace-separated words are in the reference?",answer:r.referenceLength,why:"Count whitespace-separated reference words."}}}}
];
